def L(pred, args, neg=False):
    return Literal(Atom(pred, args), neg)

def build():
    K = PolynomialSemiring(NatSemiring())          # N[X]
    e = DatalogEngine(K)
    e.add_rule(Atom("route", ("?x","?y")), [L("edge", ("?x","?y"))])
    e.add_rule(Atom("route", ("?x","?y")), [L("blue", ("?x","?y"))])
    e.add_rule(Atom("reach", ("?x","?y")), [L("route", ("?x","?y"))])
