               [L("reach", ("?x","?y")), L("route", ("?y","?z"))])
    e.add_rule(Atom("safe", ("?x","?y")),
               [L("route", ("?x","?y")), L("blocked", ("?x","?y"), neg=True)])
    e.add_aggregate(AggSpec("deg", Atom("route", ("?x","?y")), ("?x",), "count"))
    return K, e

